#!/usr/bin/env python3
"""One-off builder for data/candidates.json. Source of truth for the fetch pipeline."""
import json

P = []
def add(slug, name, cat, home=None, pricing=None, docs=None, llms=None, note=""):
    P.append({"slug": slug, "name": name, "category": cat, "home": home,
              "pricing": pricing, "docs": docs, "llms": llms, "note": note})

